if (event.type === "connected") {
  if (!peers.includes(event.peer) && peers.length < maxPeers) {
    return [...peers, event.peer].sort();
  } else {
    return [...peers].sort();
  }
} else if (event.type === "disconnected") {
  return peers.filter(p => p !== event.peer).sort();
} else {
  return [...peers].sort();
}
